package com.smarthealth.config;
import com.smarthealth.ai.*;import com.smarthealth.dao.*;import com.smarthealth.model.*;import com.smarthealth.service.*;import com.smarthealth.util.PasswordUtil;import com.smarthealth.web.*;import io.javalin.Javalin;import java.io.*;import java.nio.file.*;import java.nio.channels.*;import java.sql.*;import java.time.*;import java.util.*;
/** Manual dependency wiring, database startup, and demo seeding. */public class AppConfig{private final Properties props=new Properties();private ConnectionManager db;private ReminderScheduler scheduler;private SensorSimulator simulator;private final EventBus events=new EventBus();private Javalin app;private FileChannel lockChannel;private FileLock appLock;public AppConfig(){try(InputStream in=getClass().getResourceAsStream("/application.properties")){props.load(in);}catch(Exception e){throw new IllegalStateException("Could not load configuration",e);}}public void start(){int port=Integer.parseInt(System.getenv().getOrDefault("PORT",props.getProperty("app.port","7070")));boolean demo=Boolean.parseBoolean(System.getenv().getOrDefault("APP_DEMO_MODE",props.getProperty("app.demo.mode","true")));if(!acquireInstanceLock())return;try{db=new ConnectionManager(System.getenv().getOrDefault("APP_DB_URL",props.getProperty("app.db.url","jdbc:h2:file:./data/healthdb")));db.initialize();if(demo)seed();}catch(RuntimeException e){if(isDatabaseLocked(e)){System.out.println("Health database is already open in another app instance. Close that instance, then start the app again.");releaseInstanceLock();return;}throw e;}boolean useReal=Boolean.parseBoolean(props.getProperty("app.ai.useReal","false"));String apiKey=System.getenv("NVIDIA_API_KEY");boolean liveAi=!demo&&useReal&&apiKey!=null&&!apiKey.isBlank();boolean useRealChat=Boolean.parseBoolean(System.getenv().getOrDefault("APP_AI_CHAT_USE_REAL",props.getProperty("app.ai.chat.useReal","true")));boolean liveChatAi=useRealChat&&apiKey!=null&&!apiKey.isBlank();AIService ai=AIServiceFactory.create(demo,useReal,apiKey,props.getProperty("app.ai.provider","nvidia"),props.getProperty("app.ai.url"),props.getProperty("app.ai.model"));AIService chatAi=AIServiceFactory.create(false,useRealChat,apiKey,props.getProperty("app.ai.provider","nvidia"),props.getProperty("app.ai.url"),props.getProperty("app.ai.model"));HeartDiseaseDetector detector=new HeartDiseaseDetector(ai);List<HealthService> services=List.of(new MedicalReminder(),detector);services.forEach(HealthService::performService);scheduler=new ReminderScheduler(db,events);scheduler.start();if(demo){simulator=new SensorSimulator(db,events,detector);simulator.start();}app=ApiRoutes.create(db,detector,events,demo,liveAi,liveChatAi,ai,chatAi,System.getenv("GOOGLE_CLIENT_ID"));app.start(port);Runtime.getRuntime().addShutdownHook(new Thread(()->{if(scheduler!=null)scheduler.close();if(simulator!=null)simulator.close();if(app!=null)app.stop();if(db!=null)db.close();releaseInstanceLock();}));System.out.println("Smart Health Assistant running at http://localhost:"+port);}
 private boolean acquireInstanceLock(){try{Files.createDirectories(Path.of("data"));lockChannel=FileChannel.open(Path.of("data","app.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);try{appLock=lockChannel.tryLock();}catch(OverlappingFileLockException e){appLock=null;}if(appLock==null){System.out.println("Smart Health Assistant is already running. Open http://localhost:7070 and use that window.");lockChannel.close();return false;}return true;}catch(IOException e){throw new IllegalStateException("Could not acquire application lock",e);}}
 private boolean isDatabaseLocked(Throwable error){for(Throwable cause=error;cause!=null;cause=cause.getCause()){String message=cause.getMessage();if(message!=null&&(message.contains("Database may be already in use")||message.contains("The file is locked")))return true;}return false;}
 private void releaseInstanceLock(){try{if(appLock!=null&&appLock.isValid())appLock.release();if(lockChannel!=null&&lockChannel.isOpen())lockChannel.close();}catch(IOException ignored){}}
 private void seed(){try(Connection c=db.getConnection()){try(PreparedStatement q=c.prepareStatement("SELECT COUNT(*) FROM patients");ResultSet r=q.executeQuery()){r.next();if(r.getInt(1)>0)return;}c.setAutoCommit(false);String[] names={"Nirmit","Babita","Rishab"};for(int i=0;i<names.length;i++){long id=i+1;try(PreparedStatement p=c.prepareStatement("INSERT INTO patients VALUES(?,?,?,?,?,?)")){p.setLong(1,id);p.setString(2,names[i]);p.setInt(3,34+i*8);p.setString(4,i==1?"Female":"Male");p.setString(5,"Routine health monitoring");p.setString(6,names[i].toLowerCase()+"@example.com");p.executeUpdate();}String salt=PasswordUtil.salt();try(PreparedStatement p=c.prepareStatement("INSERT INTO users(patient_id,username,password_hash,salt) VALUES(?,?,?,?)")){p.setLong(1,id);p.setString(2,i==0?"demo":names[i].toLowerCase());p.setString(3,PasswordUtil.hash(i==0?"demo123":"demo123",salt));p.setString(4,salt);p.executeUpdate();}String[] meds={"Paracetamol","Vitamin D3","Atorvastatin","Omega 3","Metformin","Calcium"};for(int j=0;j<meds.length;j++){try(PreparedStatement p=c.prepareStatement("INSERT INTO medicines(patient_id,name,dosage,instructions,start_date,end_date,frequency) VALUES(?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,id);p.setString(2,meds[j]);p.setString(3,j==0?"500 mg":"1 tablet");p.setString(4,"Take with water as directed");p.setDate(5,java.sql.Date.valueOf(LocalDate.now().minusDays(30)));p.setDate(6,java.sql.Date.valueOf(LocalDate.now().plusDays(60)));p.setString(7,"Daily");p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();long mid=k.getLong(1);if(j<2){try(PreparedStatement a=c.prepareStatement("INSERT INTO reminders(medicine_id,reminder_time,schedule,status) VALUES(?,?,?,'PENDING')")){a.setLong(1,mid);a.setTimestamp(2,Timestamp.valueOf(LocalDateTime.now().plusSeconds(45+j*40)));a.setString(3,"Daily");a.executeUpdate();}}}}}}for(int day=6;day>=0;day--)for(int j=0;j<3;j++){try(PreparedStatement p=c.prepareStatement("INSERT INTO sensor_data(patient_id,heart_rate,systolic_bp,diastolic_bp,spo2,recorded_at,source) VALUES(1,?,?,?,?,?,?)")){p.setInt(1,72+j*3);p.setInt(2,118+j*2);p.setInt(3,78);p.setInt(4,97);p.setTimestamp(5,Timestamp.valueOf(LocalDateTime.now().minusDays(day).minusHours(j*5)));p.setString(6,"Seed data");p.executeUpdate();}}c.commit();}catch(SQLException e){throw new IllegalStateException("Could not seed demo",e);}}
}


